package com.srm.inventory.config;
import com.srm.inventory.entity.Product; import com.srm.inventory.repository.ProductRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.math.BigDecimal;
@Configuration public class DemoData { @Bean CommandLineRunner seed(ProductRepository repo){return args->{if(repo.count()==0){ add(repo,"Canvas Tote Bag","BAG-001","8.00","12.50",18,8,"Accessories"); add(repo,"Ceramic Mug","MUG-001","5.00","8.00",4,6,"Homeware"); add(repo,"Notebook Set","NOTE-001","4.00","6.75",30,10,"Stationery"); add(repo,"Water Bottle","BOT-001","10.00","15.00",2,5,"Accessories"); }};} private void add(ProductRepository r,String n,String s,String cost,String price,int stock,int level,String cat){Product p=new Product();p.setName(n);p.setSku(s);p.setCostPrice(new BigDecimal(cost));p.setPrice(new BigDecimal(price));p.setStockQuantity(stock);p.setReorderLevel(level);p.setCategory(cat);r.save(p);} }
